/// <summary>
/// Durable interpreted-module operation result.
/// </summary>
[DataContract]
public final class MXTXppInterpreterModuleResponse
{
    boolean success;
    str error;
    str moduleName;
    int version;
    int activeVersion;
    int previousActiveVersion;
    str state;
    str sourceCode;
    str sourceHash;
    List dependencies = new List(Types::String);
    List versions = new List(Types::String);
    str deployedBy;
    str deployedAt;
    int instructionCount;
    boolean cacheHit;
    int64 compileMicroseconds;
}
